import React, { useState } from 'react';
import { Layout } from '../components/Layout';
import { User, AttendanceSession } from '../types';
import { DEPARTMENTS, COURSES, LEVELS, GEOCONFIG } from '../constants';

interface LecturerDashboardProps {
  user: User | null;
  onLogout: () => void;
  onStartSession: (session: AttendanceSession) => void;
}

export const LecturerDashboard: React.FC<LecturerDashboardProps> = ({ user, onLogout, onStartSession }) => {
  const [selectedDept, setSelectedDept] = useState('');
  const [selectedLevel, setSelectedLevel] = useState('');
  const [selectedCourse, setSelectedCourse] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const filteredCourses = COURSES.filter(c => c.deptId === selectedDept);

  const handleStartSession = () => {
    if (!selectedDept || !selectedLevel || !selectedCourse) {
      setError('Please complete all selections.');
      return;
    }

    setLoading(true);
    setError('');

    // Request location
    if (!navigator.geolocation) {
      setError('Geolocation is not supported by your browser.');
      setLoading(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const sessionKey = Math.random().toString(36).substr(2, 6).toUpperCase();
        const sessionId = Math.random().toString(36).substr(2, 9);

        const newSession: AttendanceSession = {
          id: sessionId,
          lecturerId: user?.id || 'anonymous',
          courseId: selectedCourse,
          departmentId: selectedDept,
          level: selectedLevel,
          sessionKey,
          startTime: Date.now(),
          location: {
            lat: position.coords.latitude,
            lng: position.coords.longitude
          },
          radius: GEOCONFIG.DEFAULT_RADIUS,
          active: true
        };

        onStartSession(newSession);
        setLoading(false);
      },
      (err) => {
        setError('Failed to get your location. Please enable location services.');
        setLoading(false);
      }
    );
  };

  return (
    <Layout title="Lecturer Dashboard" onLogout={onLogout} showLogout>
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-2xl shadow-sm border p-6">
            <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center">
              <i className="fas fa-plus-circle text-blue-600 mr-2"></i>
              Start New Session
            </h2>

            <div className="space-y-6">
              {/* College is hardcoded to Engineering as requested */}
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">College</label>
                <div className="w-full px-4 py-3 bg-gray-100 border border-gray-200 rounded-xl text-gray-600 font-medium">
                  College of Engineering
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Department</label>
                  <select
                    value={selectedDept}
                    onChange={(e) => { setSelectedDept(e.target.value); setSelectedCourse(''); }}
                    className="w-full px-4 py-3 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  >
                    <option value="">Select Department</option>
                    {DEPARTMENTS.map(d => (
                      <option key={d.id} value={d.id}>{d.name}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Level</label>
                  <select
                    value={selectedLevel}
                    onChange={(e) => setSelectedLevel(e.target.value)}
                    className="w-full px-4 py-3 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  >
                    <option value="">Select Level</option>
                    {LEVELS.map(l => (
                      <option key={l} value={l}>{l} Level</option>
                    ))}
                  </select>
                </div>
              </div>

              {selectedDept && (
                <div className="animate-in fade-in slide-in-from-top-2 duration-300">
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Course</label>
                  <select
                    value={selectedCourse}
                    onChange={(e) => setSelectedCourse(e.target.value)}
                    className="w-full px-4 py-3 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  >
                    <option value="">Select Course</option>
                    {filteredCourses.map(c => (
                      <option key={c.id} value={c.id}>{c.code} - {c.name}</option>
                    ))}
                  </select>
                </div>
              )}

              {error && (
                <div className="bg-red-50 text-red-600 p-4 rounded-xl flex items-center space-x-2 text-sm">
                  <i className="fas fa-exclamation-circle"></i>
                  <span>{error}</span>
                </div>
              )}

              <button
                onClick={handleStartSession}
                disabled={loading}
                className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-bold py-4 rounded-xl shadow-lg transition-all flex items-center justify-center space-x-2 text-lg"
              >
                {loading ? (
                  <i className="fas fa-circle-notch fa-spin"></i>
                ) : (
                  <>
                    <i className="fas fa-satellite-dish"></i>
                    <span>Generate Session & Link</span>
                  </>
                )}
              </button>
            </div>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white rounded-2xl shadow-sm border p-6">
            <h3 className="text-lg font-bold text-gray-800 mb-4">Quick Stats</h3>
            <div className="space-y-4">
              <div className="flex justify-between items-center p-3 bg-blue-50 rounded-xl">
                <span className="text-gray-600 text-sm font-medium">Semester Attendance</span>
                <span className="text-blue-700 font-bold">75% Target</span>
              </div>
              <div className="flex justify-between items-center p-3 bg-green-50 rounded-xl">
                <span className="text-gray-600 text-sm font-medium">Total Courses</span>
                <span className="text-green-700 font-bold">{COURSES.length}</span>
              </div>
            </div>
          </div>

          <div className="bg-gradient-to-br from-blue-600 to-indigo-700 rounded-2xl shadow-lg p-6 text-white">
            <h3 className="text-lg font-bold mb-2">How it works</h3>
            <ul className="space-y-3 text-sm text-blue-100">
              <li className="flex items-start space-x-2">
                <i className="fas fa-check-circle mt-1"></i>
                <span>Select your course and level to begin.</span>
              </li>
              <li className="flex items-start space-x-2">
                <i className="fas fa-check-circle mt-1"></i>
                <span>Share the generated link & session key with students.</span>
              </li>
              <li className="flex items-start space-x-2">
                <i className="fas fa-check-circle mt-1"></i>
                <span>Students must be within range to submit attendance.</span>
              </li>
            </ul>
          </div>
        </div>
      </div>
    </Layout>
  );
};

import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { Layout } from '../components/Layout';
import { User, AttendanceSession, AttendanceRecord, StudentStats } from '../types';
import { COURSES, DEPARTMENTS } from '../constants';
import { analyzeAttendance } from '../services/geminiService';

interface SessionViewProps {
  user: User | null;
  activeSession: AttendanceSession | null;
  onLogout: () => void;
}

export const SessionView: React.FC<SessionViewProps> = ({ user, activeSession, onLogout }) => {
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [aiInsights, setAiInsights] = useState<string>('');
  const [analyzing, setAnalyzing] = useState(false);

  // Poll for simulated new records every few seconds
  useEffect(() => {
    if (!activeSession) return;

    // In a real app, this would be a WebSocket or Firebase listener
    const interval = setInterval(() => {
      // Mocking student attendance every now and then
      if (Math.random() > 0.7) {
        const mockStudent = {
          id: Math.random().toString(36).substr(2, 9),
          sessionId: activeSession.id,
          studentName: `Student ${Math.floor(Math.random() * 100)}`,
          matricNo: `ENG/${new Date().getFullYear()}/${Math.floor(1000 + Math.random() * 9000)}`,
          department: activeSession.departmentId,
          timestamp: Date.now(),
          location: activeSession.location
        };
        setRecords(prev => [mockStudent, ...prev]);
      }
    }, 5000);

    return () => clearInterval(interval);
  }, [activeSession]);

  const runAiAnalysis = async () => {
    setAnalyzing(true);
    // Mocking some semester history for AI analysis
    const mockStats: StudentStats[] = records.map(r => ({
      matricNo: r.matricNo,
      name: r.studentName,
      sessionsAttended: Math.floor(Math.random() * 10) + 1,
      totalSessions: 12,
      percentage: 0
    })).map(s => ({ ...s, percentage: (s.sessionsAttended / s.totalSessions) * 100 }));

    const insight = await analyzeAttendance(mockStats);
    setAiInsights(insight);
    setAnalyzing(false);
  };

  if (!activeSession) {
    return (
      <Layout onLogout={onLogout} showLogout>
        <div className="text-center py-20">
          <h2 className="text-2xl font-bold text-gray-800">No active session found.</h2>
          <Link to="/dashboard" className="text-blue-600 font-semibold hover:underline mt-4 inline-block">Return to Dashboard</Link>
        </div>
      </Layout>
    );
  }

  const course = COURSES.find(c => c.id === activeSession.courseId);
  const portalUrl = `${window.location.origin}${window.location.pathname}#/portal/${activeSession.id}`;

  return (
    <Layout title="Live Session Tracking" onLogout={onLogout} showLogout>
      <div className="space-y-6">
        <div className="bg-white rounded-2xl shadow-sm border p-6 overflow-hidden">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <span className="inline-block px-3 py-1 bg-green-100 text-green-700 text-xs font-bold rounded-full mb-2 uppercase tracking-wider">
