  const [department, setDepartment] = useState('');
  const [sessionKey, setSessionKey] = useState('');
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [message, setMessage] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setStatus('idle');
    setMessage('');

    // Verification Logic:
    // 1. Check Geolocation
    if (!navigator.geolocation) {
      setStatus('error');
      setMessage('Geolocation must be enabled to take attendance.');
      setLoading(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        // In a real app, we'd send these coords to the server to compare with activeSession.location
        // For this demo, we simulate the range check:
        setTimeout(() => {
          // Check session key (simulated check)
          if (sessionKey.length !== 6) {
            setStatus('error');
            setMessage('Invalid session key format.');
            setLoading(false);
            return;
          }

          setStatus('success');
          setMessage(`Attendance successfully logged for ${name}! You are within the lecture zone.`);
          setLoading(false);
          // Reset form on success
          setName('');
          setMatricNo('');
          setDepartment('');
          setSessionKey('');
        }, 1500);
      },
      (err) => {
        setStatus('error');
        setMessage('Location access denied. Attendance cannot be verified without location.');
        setLoading(false);
      },
      { enableHighAccuracy: true }
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4 md:p-8">
