import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { Layout } from '../components/Layout';
import { User, AttendanceSession, AttendanceRecord, StudentStats } from '../types';
import { COURSES, DEPARTMENTS } from '../constants';
import { analyzeAttendance } from '../services/geminiService';

interface SessionViewProps {
  user: User | null;
  activeSession: AttendanceSession | null;
  onLogout: () => void;
  onEndSession: (sessionId: string) => void;
}

export const SessionView: React.FC<SessionViewProps> = ({ user, activeSession, onLogout, onEndSession }) => {
  const { sessionId } = useParams<{ sessionId: string }>();
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [aiInsights, setAiInsights] = useState<string>('');
  const [analyzing, setAnalyzing] = useState(false);
  const navigate = useNavigate();

  // Load records for this session in real-time
  useEffect(() => {
    const fetchRecords = () => {
      const allRecords: AttendanceRecord[] = JSON.parse(localStorage.getItem('attendx_records') || '[]');
      const filtered = allRecords.filter(r => r.sessionId === sessionId);
      setRecords(filtered.sort((a, b) => b.timestamp - a.timestamp));
    };

    fetchRecords();

    // Listen for storage events (student submissions from other windows)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'attendx_records') {
        fetchRecords();
      }
    };
    window.addEventListener('storage', handleStorageChange);

    // Also poll every few seconds just in case some browsers don't trigger storage event on same page
    const interval = setInterval(fetchRecords, 3000);

    return () => {
      window.removeEventListener('storage', handleStorageChange);
      clearInterval(interval);
    };
  }, [sessionId]);

  const runAiAnalysis = async () => {
    setAnalyzing(true);
    // Real stats based on current session and some history
    const allSessions: AttendanceSession[] = JSON.parse(localStorage.getItem('attendx_sessions') || '[]');
    const courseSessions = allSessions.filter(s => s.courseId === activeSession?.courseId);

    const mockStats: StudentStats[] = records.map(r => ({
      matricNo: r.matricNo,
      name: r.studentName,
      sessionsAttended: Math.floor(Math.random() * courseSessions.length) + 1,
      totalSessions: courseSessions.length,
      percentage: 0,
      eligible: false
    })).map(s => {
      const pct = (s.sessionsAttended / s.totalSessions) * 100;
      return { ...s, percentage: pct, eligible: pct >= 75 };
    });

    const insight = await analyzeAttendance(mockStats);
    setAiInsights(insight);
    setAnalyzing(false);
  };

  if (!activeSession && !sessionId) {
    return (
      <Layout onLogout={onLogout} showLogout>
        <div className="text-center py-20">
          <h2 className="text-2xl font-bold text-gray-800">No active session found.</h2>
          <Link to="/dashboard" className="text-blue-600 font-semibold hover:underline mt-4 inline-block">Return to Dashboard</Link>
        </div>
      </Layout>
    );
  }

  // If session is ended but we are viewing it
  const sessions: AttendanceSession[] = JSON.parse(localStorage.getItem('attendx_sessions') || '[]');
  const sessionData = activeSession || sessions.find(s => s.id === sessionId);

  if (!sessionData) {
    return (
      <Layout onLogout={onLogout} showLogout>
        <div className="text-center py-20">
          <h2 className="text-2xl font-bold text-gray-800">Session data unavailable.</h2>
          <Link to="/dashboard" className="text-blue-600 font-semibold hover:underline mt-4 inline-block">Return to Dashboard</Link>
        </div>
      </Layout>
    );
  }

  const course = COURSES.find(c => c.id === sessionData.courseId);
  const portalUrl = `${window.location.origin}${window.location.pathname}#/portal/${sessionData.id}`;

  return (
    <Layout title="Live Session Tracking" onLogout={onLogout} showLogout>
      <div className="space-y-6">
        <div className="bg-white rounded-2xl shadow-sm border p-6 overflow-hidden">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <span className={`inline-block px-3 py-1 text-xs font-bold rounded-full mb-2 uppercase tracking-wider ${sessionData.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}`}>
                {sessionData.active ? 'Live Session' : 'Past Session'}
              </span>
              <h1 className="text-2xl font-bold text-gray-900">{course?.name} ({course?.code})</h1>
              <p className="text-gray-500 font-medium">Level: {sessionData.level} | Dept: {DEPARTMENTS.find(d => d.id === sessionData.departmentId)?.name}</p>
            </div>
            {sessionData.active && (
              <div className="bg-blue-600 text-white px-6 py-4 rounded-2xl text-center shadow-lg border-b-4 border-blue-800">
                <p className="text-xs font-bold uppercase tracking-widest text-blue-100 mb-1">Session Key</p>
                <p className="text-3xl font-black tracking-widest">{sessionData.sessionKey}</p>
              </div>
            )}
          </div>

          {sessionData.active && (
            <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="p-4 bg-gray-50 rounded-xl border border-dashed border-gray-300">
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">One-Time Attendance Link</label>
                <div className="flex items-center space-x-2">
                  <input 
                    readOnly 
                    value={portalUrl}
                    className="flex-1 bg-white border rounded-lg px-3 py-2 text-sm text-gray-600 outline-none truncate"
                  />
                  <button 
                    onClick={() => {
                      navigator.clipboard.writeText(portalUrl);
                      alert('Link copied to clipboard!');
                    }}
                    className="bg-gray-800 text-white p-2 rounded-lg hover:bg-black transition-colors"
                    title="Copy link"
                  >
                    <i className="fas fa-copy"></i>
                  </button>
                </div>
              </div>
              <div className="flex items-center justify-center p-4 bg-blue-50 rounded-xl">
                <div className="text-center">
                  <span className="text-blue-700 text-3xl font-black">{records.length}</span>
                  <p className="text-blue-600 text-xs font-bold uppercase">Students Present</p>
                </div>
              </div>
            </div>
          )}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border overflow-hidden">
            <div className="p-4 border-b flex justify-between items-center">
              <h3 className="font-bold text-gray-800">Attendance Log</h3>
              <span className="text-xs text-gray-400">Total: {records.length} entries</span>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase">Matric No</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase">Name</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase">Time</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {records.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-10 text-center text-gray-400 italic">
                        {sessionData.active ? 'Waiting for students to log attendance...' : 'No records found for this session.'}
                      </td>
                    </tr>
                  ) : (
                    records.map(record => (
                      <tr key={record.id} className="hover:bg-blue-50 transition-colors">
                        <td className="px-6 py-4 text-sm font-semibold text-gray-900">{record.matricNo}</td>
                        <td className="px-6 py-4 text-sm text-gray-700">{record.studentName}</td>
                        <td className="px-6 py-4 text-sm text-gray-500">{new Date(record.timestamp).toLocaleTimeString()}</td>
                        <td className="px-6 py-4">
                          <span className="px-2 py-1 bg-green-100 text-green-700 text-[10px] font-bold rounded uppercase">Verified</span>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>

          <div className="space-y-6">
            <div className="bg-white rounded-2xl shadow-sm border p-6">
              <div className="flex items-center justify-between mb-4">
                <h3 className="font-bold text-gray-800">AI Insight Engine</h3>
                <i className="fas fa-microchip text-blue-500"></i>
              </div>
              <p className="text-sm text-gray-500 mb-6">
                Analyze student achievement relative to the 75% threshold.
              </p>
              {aiInsights ? (
                <div className="bg-blue-50 p-4 rounded-xl text-sm text-blue-800 mb-4 animate-in fade-in zoom-in">
                  <div className="flex items-start space-x-2">
                    <i className="fas fa-quote-left text-blue-300 mt-1"></i>
                    <p className="italic leading-relaxed">{aiInsights}</p>
                  </div>
                </div>
              ) : null}
              <button 
                onClick={runAiAnalysis}
                disabled={analyzing || records.length === 0}
                className="w-full bg-gray-900 hover:bg-black disabled:bg-gray-300 text-white font-bold py-3 rounded-xl transition-all flex items-center justify-center space-x-2 shadow-md"
              >
                {analyzing ? (
                  <i className="fas fa-circle-notch fa-spin"></i>
                ) : (
                  <>
                    <i className="fas fa-brain"></i>
                    <span>Analyze Attendance</span>
                  </>
                )}
              </button>
            </div>

            {sessionData.active ? (
              <div className="bg-red-50 rounded-2xl border border-red-100 p-6">
                <h3 className="font-bold text-red-800 mb-2">End Session</h3>
                <p className="text-sm text-red-600 mb-4">Once ended, the session key and link will expire permanently.</p>
                <button 
                  onClick={() => onEndSession(sessionData.id)}
                  className="w-full bg-red-600 hover:bg-red-700 text-white font-bold py-3 rounded-xl transition-all flex items-center justify-center space-x-2 shadow-sm"
                >
                  <i className="fas fa-power-off"></i>
                  <span>Terminate Session</span>
                </button>
              </div>
            ) : (
              <div className="bg-gray-50 rounded-2xl border border-gray-200 p-6">
                 <Link 
                  to="/history" 
                  className="w-full bg-gray-800 hover:bg-black text-white font-bold py-3 rounded-xl transition-all flex items-center justify-center space-x-2 shadow-sm"
                >
                  <i className="fas fa-chevron-left"></i>
                  <span>Back to History</span>
                </Link>
              </div>
            )}
          </div>
        </div>
      </div>
    </Layout>
  );
};

import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { DEPARTMENTS } from '../constants';
import { AttendanceSession, AttendanceRecord } from '../types';

export const StudentPortal: React.FC = () => {
  const { sessionId } = useParams<{ sessionId: string }>();
  const [name, setName] = useState('');
  const [matricNo, setMatricNo] = useState('');
  const [department, setDepartment] = useState('');
  const [sessionKey, setSessionKey] = useState('');
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [message, setMessage] = useState('');
  const [activeSession, setActiveSession] = useState<AttendanceSession | null>(null);

  useEffect(() => {
    const sessions: AttendanceSession[] = JSON.parse(localStorage.getItem('attendx_sessions') || '[]');
    const found = sessions.find(s => s.id === sessionId);
    if (found) {
      setActiveSession(found);
    }
  }, [sessionId]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setStatus('idle');
    setMessage('');

    if (!activeSession || !activeSession.active) {
      setStatus('error');
      setMessage('This session is no longer active.');
      setLoading(false);
      return;
    }

    if (sessionKey.toUpperCase() !== activeSession.sessionKey) {
      setStatus('error');
      setMessage('Incorrect Session Key. Please ask your lecturer.');
      setLoading(false);
      return;
    }

    if (!navigator.geolocation) {
      setStatus('error');
      setMessage('Geolocation must be enabled to take attendance.');
      setLoading(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        // Calculate distance (very rough simplification for demo)
        const latDiff = Math.abs(position.coords.latitude - activeSession.location.lat);
        const lngDiff = Math.abs(position.coords.longitude - activeSession.location.lng);

        // Approx 100m threshold
        if (latDiff > 0.001 || lngDiff > 0.001) {
           setStatus('error');
           setMessage('Outside lecture range. Attendance denied.');
           setLoading(false);
           return;
        }

        setTimeout(() => {
          // Save Record
          const records: AttendanceRecord[] = JSON.parse(localStorage.getItem('attendx_records') || '[]');

          // Check if student already submitted for this session
          const alreadySubmitted = records.some(r => r.sessionId === sessionId && r.matricNo === matricNo);
          if (alreadySubmitted) {
            setStatus('error');
            setMessage('You have already logged attendance for this session.');
            setLoading(false);
            return;
          }

          const newRecord: AttendanceRecord = {
            id: Math.random().toString(36).substr(2, 9),
            sessionId: sessionId!,
            studentName: name,
            matricNo: matricNo.toUpperCase(),
            department: department,
            timestamp: Date.now(),
            location: {
              lat: position.coords.latitude,
              lng: position.coords.longitude
            }
          };

          localStorage.setItem('attendx_records', JSON.stringify([...records, newRecord]));

          setStatus('success');
          setMessage(`Attendance successfully logged for ${name}!`);
          setLoading(false);
          setName('');
          setMatricNo('');
          setDepartment('');
          setSessionKey('');
        }, 1000);
      },
      (err) => {
        setStatus('error');
        setMessage('Location access denied. Attendance cannot be verified.');
        setLoading(false);
      },
      { enableHighAccuracy: true }
    );
  };

  if (!activeSession) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 rounded-2xl shadow-lg text-center">
          <i className="fas fa-exclamation-triangle text-red-500 text-4xl mb-4"></i>
          <h2 className="text-xl font-bold">Invalid Session</h2>
          <p className="text-gray-500">The attendance link you followed is invalid or has expired.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4 md:p-8">
      <div className="w-full max-w-xl bg-white rounded-3xl shadow-2xl overflow-hidden">
        <div className="bg-blue-600 p-8 text-white text-center">
          <div className="bg-blue-500 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-inner">
            <i className="fas fa-university text-3xl"></i>
          </div>
          <h1 className="text-2xl font-black tracking-tight">Student Attendance Portal</h1>
          <p className="text-blue-100 mt-2 text-sm">Logging for session at: {new Date(activeSession.startTime).toLocaleTimeString()}</p>
        </div>

        <div className="p-8 md:p-10">
          {status === 'success' ? (
            <div className="animate-in zoom-in duration-300 text-center space-y-4">
              <div className="bg-green-100 text-green-600 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
                <i className="fas fa-check text-4xl"></i>
              </div>
              <h2 className="text-2xl font-bold text-gray-900">Verified!</h2>
              <p className="text-gray-600 px-4">{message}</p>
              <button 
                onClick={() => setStatus('idle')}
                className="mt-6 text-blue-600 font-bold hover:underline"
              >
                Done
              </button>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-5">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1.5">Full Name</label>
                  <input
                    type="text"
                    required
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-gray-800"
                    placeholder="Jane Doe"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1.5">Matric Number</label>
                  <input
                    type="text"
                    required
                    value={matricNo}
                    onChange={(e) => setMatricNo(e.target.value)}
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-gray-800"
                    placeholder="ENG/21/0000"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1.5">Department</label>
                <select
                  required
                  value={department}
                  onChange={(e) => setDepartment(e.target.value)}
                  className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-gray-800 appearance-none"
                >
                  <option value="">Choose Department</option>
                  {DEPARTMENTS.map(d => (
                    <option key={d.id} value={d.id}>{d.name}</option>
                  ))}
                </select>
              </div>

              <div className="bg-blue-50 p-6 rounded-2xl border-2 border-dashed border-blue-200">
                <label className="block text-center text-xs font-bold text-blue-500 uppercase tracking-widest mb-3">One-Time Session Key</label>
                <input
                  type="text"
                  required
                  maxLength={6}
                  value={sessionKey}
                  onChange={(e) => setSessionKey(e.target.value.toUpperCase())}
                  className="w-full text-center text-3xl font-black tracking-[0.5em] py-4 bg-white border border-blue-200 rounded-xl focus:ring-4 focus:ring-blue-100 outline-none transition-all text-blue-700 uppercase"
                  placeholder="------"
                />
              </div>

              {status === 'error' && (
                <div className="bg-red-50 text-red-600 p-4 rounded-xl flex items-center space-x-2 text-sm animate-in slide-in-from-bottom-2">
                  <i className="fas fa-exclamation-circle"></i>
                  <span>{message}</span>
                </div>
              )}

              <button
                type="submit"
                disabled={loading}
                className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-black py-4 rounded-2xl shadow-xl transition-all flex items-center justify-center space-x-3 text-lg uppercase tracking-wider mt-4"
              >
                {loading ? (
                  <i className="fas fa-circle-notch fa-spin"></i>
                ) : (
                  <>
                    <i className="fas fa-paper-plane"></i>
                    <span>Submit Attendance</span>
                  </>
                )}
              </button>
            </form>
          )}
        </div>
      </div>

      <div className="mt-8 text-center text-gray-400 text-xs font-medium space-y-1">
        <p>Geo-fencing active. Must reach 75% for exam eligibility.</p>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Layout } from '../components/Layout';
import { AttendanceSession, AttendanceRecord } from '../types';
import { COURSES, DEPARTMENTS } from '../constants';

interface HistoryViewProps {
  onLogout: () => void;
}

export const HistoryView: React.FC<HistoryViewProps> = ({ onLogout }) => {
