              </button>
              <Link to="/dashboard" className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-xl flex items-center space-x-2 transition-colors shadow-md">
                <i className="fas fa-chevron-left text-xs"></i>
