  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 400 }, height: { ideal: 400 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setCameraActive(true);
      }
    } catch (err) {
      console.error("Camera access denied:", err);
    }
  };

  const captureImage = () => {
    if (canvasRef.current && videoRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        context.drawImage(videoRef.current, 0, 0, 300, 300);
        return canvasRef.current.toDataURL('image/jpeg', 0.6);
      }
    }
    return undefined;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    performAttendanceCheck();
  };

  const performAttendanceCheck = () => {
    setLoading(true);
    setStatus('idle');
    setMessage('');

    if (!activeSession || !activeSession.active) {
      setStatus('error');
      setMessage('This session is no longer active.');
      setLoading(false);
      return;
    }

    const deviceLockKey = `attendx_lock_${sessionId}`;
    const lockedMatric = localStorage.getItem(deviceLockKey);

    if (lockedMatric && lockedMatric.toUpperCase() !== matricNo.toUpperCase()) {
      setStatus('error');
      setMessage(`Security Alert: This device is already locked to ${lockedMatric}. Only one student per device.`);
      setLoading(false);
      return;
    }

    if (sessionKey.toUpperCase() !== activeSession.sessionKey) {
      setStatus('error');
      setMessage('Incorrect Session Key.');
      setLoading(false);
      return;
    }

    const faceImage = captureImage();
    if (!faceImage && cameraActive) {
      setStatus('error');
      setMessage('Face verification failed. Ensure your face is visible to the camera.');
      setLoading(false);
      return;
    }

    // ROBUST LOCATION HANDLER
    const getLocation = (useHighAccuracy: boolean, timeout: number) => {
      return new Promise<GeolocationPosition>((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, {
          enableHighAccuracy: useHighAccuracy,
          timeout: timeout,
          maximumAge: useHighAccuracy ? 0 : 60000
        });
      });
    };

    // Multi-stage Attempt
    (async () => {
      let position: GeolocationPosition;
      try {
        // Stage 1: Fast High-Accuracy attempt
        position = await getLocation(true, 7000);
      } catch (err) {
        try {
          // Stage 2: Fallback to Low-Accuracy (Cell/Wi-Fi) - Much more reliable indoors
          console.log("Falling back to low accuracy location...");
          position = await getLocation(false, 10000);
        } catch (finalErr) {
          setStatus('error');
          setMessage('Location failure: GPS/Network signal too weak indoors. Please step closer to a window or exit.');
          setLoading(false);
          return;
        }
      }

      const distance = getDistanceInMeters(
        position.coords.latitude,
        position.coords.longitude,
        activeSession.location.lat,
        activeSession.location.lng
      );

      const allowedRadius = activeSession.radius + 60; // Slightly increased buffer for indoor drift

      if (distance > allowedRadius) {
         setStatus('error');
         setMessage(`Outside lecture range (${Math.round(distance)}m away). Please move closer.`);
         setLoading(false);
         return;
      }

      const records: AttendanceRecord[] = JSON.parse(localStorage.getItem('attendx_records') || '[]');
      const alreadySubmitted = records.some(r => r.sessionId === sessionId && r.matricNo.toUpperCase() === matricNo.toUpperCase());

      if (alreadySubmitted) {
        setStatus('error');
        setMessage('Attendance already logged.');
        setLoading(false);
        return;
      }

      const newRecord: AttendanceRecord = {
        id: Math.random().toString(36).substr(2, 9),
        sessionId: sessionId!,
        studentName: name,
        matricNo: matricNo.toUpperCase(),
        department: department,
        timestamp: Date.now(),
        faceImage: faceImage,
        location: {
          lat: position.coords.latitude,
          lng: position.coords.longitude
        }
      };

      localStorage.setItem('attendx_records', JSON.stringify([...records, newRecord]));
      localStorage.setItem(deviceLockKey, matricNo.toUpperCase());

      setStatus('success');
      setMessage(`Attendance successfully logged for ${name}!`);
      setLoading(false);
    })();
  };

  if (!activeSession) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 rounded-2xl shadow-lg text-center max-w-sm">
          <i className="fas fa-exclamation-triangle text-red-500 text-4xl mb-4"></i>
          <h2 className="text-xl font-bold text-gray-800">Invalid Link</h2>
          <button onClick={() => window.location.reload()} className="mt-6 text-blue-600 font-bold">Retry</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4 md:p-8">
      <div className="w-full max-w-xl bg-white rounded-3xl shadow-2xl overflow-hidden border border-gray-100">
        <div className="bg-blue-600 p-6 text-white text-center">
          <h1 className="text-xl font-black uppercase tracking-tight">Attendance Verification</h1>
          <div className="mt-2 inline-flex items-center space-x-2 bg-blue-700 px-3 py-1 rounded-full text-[9px] font-bold uppercase tracking-widest text-blue-100">
             <i className="fas fa-video"></i>
             <span>Biometric + Location Auth Active</span>
          </div>
        </div>

        <div className="p-8 md:p-10">
          {status === 'success' ? (
            <div className="text-center space-y-4 animate-in zoom-in">
              <div className="bg-green-100 text-green-600 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
                <i className="fas fa-check text-4xl"></i>
              </div>
              <h2 className="text-2xl font-bold text-gray-900">Successfully Verified</h2>
              <p className="text-gray-600 px-4">{message}</p>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Camera Viewfinder */}
              <div className="relative group overflow-hidden rounded-2xl bg-black aspect-square max-w-[200px] mx-auto border-4 border-gray-100 shadow-inner">
                {!cameraActive && (
                   <div className="absolute inset-0 flex flex-col items-center justify-center text-white p-4 text-center">
                      <i className="fas fa-camera-slash text-2xl mb-2 opacity-50"></i>
                      <p className="text-[10px] uppercase font-bold text-gray-400">Enable Camera Access</p>
                   </div>
                )}
                <video 
                  ref={videoRef} 
                  autoPlay 
                  playsInline 
                  muted 
                  className="w-full h-full object-cover grayscale brightness-110 contrast-125"
                />
                <div className="absolute inset-0 border-[20px] border-black/10 pointer-events-none"></div>
                <div className="absolute top-4 left-4 border-l-2 border-t-2 border-blue-400 w-4 h-4"></div>
                <div className="absolute top-4 right-4 border-r-2 border-t-2 border-blue-400 w-4 h-4"></div>
                <div className="absolute bottom-4 left-4 border-l-2 border-b-2 border-blue-400 w-4 h-4"></div>
                <div className="absolute bottom-4 right-4 border-r-2 border-b-2 border-blue-400 w-4 h-4"></div>
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                   <div className="w-full h-[1px] bg-blue-500/30 animate-pulse"></div>
                </div>
                <canvas ref={canvasRef} width="300" height="300" className="hidden" />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Full Name</label>
                  <input
                    type="text" required value={name} onChange={(e) => setName(e.target.value)}
                    className="w-full px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                    placeholder="Jane Doe"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Matric Number</label>
                  <input
                    type="text" required value={matricNo} onChange={(e) => setMatricNo(e.target.value)}
                    className="w-full px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                    placeholder="ENG/21/0001"
                  />
                </div>
              </div>

              <div className="bg-blue-50 p-5 rounded-2xl border border-blue-100">
                <label className="block text-center text-[10px] font-black text-blue-500 uppercase tracking-widest mb-2">Lecture Key</label>
                <input
                  type="text" required maxLength={6} value={sessionKey} onChange={(e) => setSessionKey(e.target.toUpperCase())}
                  className="w-full text-center text-3xl font-black tracking-[0.4em] py-3 bg-white border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-400 outline-none transition-all text-blue-700"
                  placeholder="------"
                />
              </div>

              {status === 'error' && (
                <div className="bg-red-50 text-red-600 p-4 rounded-xl flex flex-col space-y-2 text-xs border border-red-100 animate-in shake">
                  <div className="flex items-center space-x-2 font-bold">
                    <i className="fas fa-exclamation-triangle"></i>
                    <span>{message}</span>
                  </div>
                </div>
              )}

              <button
                type="submit" disabled={loading}
                className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-black py-4 rounded-2xl shadow-xl transition-all flex items-center justify-center space-x-3 text-sm uppercase tracking-widest"
              >
                {loading ? <i className="fas fa-sync-alt fa-spin"></i> : <span>Verify & Log Attendance</span>}
              </button>
            </form>
          )}
        </div>
      </div>

      <div className="mt-8 text-center space-y-2">
        <p className="text-gray-400 text-[9px] font-bold uppercase tracking-widest">Geo-Fencing + Biometrics Secured</p>
        <p className="text-blue-600 text-[10px] font-black uppercase tracking-[0.2em] opacity-70">Engineered by SIENA Group</p>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { Layout } from '../components/Layout';
import { User, AttendanceSession, AttendanceRecord, StudentStats } from '../types';
import { COURSES, DEPARTMENTS } from '../constants';
import { analyzeAttendance } from '../services/geminiService';

interface SessionViewProps {
  user: User | null;
  activeSession: AttendanceSession | null;
  onLogout: () => void;
  onEndSession: (sessionId: string) => void;
}

export const SessionView: React.FC<SessionViewProps> = ({ user, activeSession, onLogout, onEndSession }) => {
  const { sessionId } = useParams<{ sessionId: string }>();
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [aiInsights, setAiInsights] = useState<string>('');
  const [analyzing, setAnalyzing] = useState(false);
  const [selectedFace, setSelectedFace] = useState<string | null>(null);

  useEffect(() => {
    const fetchRecords = () => {
      const allRecords: AttendanceRecord[] = JSON.parse(localStorage.getItem('attendx_records') || '[]');
      const filtered = allRecords.filter(r => r.sessionId === sessionId);
      setRecords(filtered.sort((a, b) => b.timestamp - a.timestamp));
    };

    fetchRecords();
    const interval = setInterval(fetchRecords, 3000);
    return () => clearInterval(interval);
  }, [sessionId]);

  const runAiAnalysis = async () => {
    if (records.length === 0) return;
    setAnalyzing(true);

    const allSessions: AttendanceSession[] = JSON.parse(localStorage.getItem('attendx_sessions') || '[]');
    const allRecords: AttendanceRecord[] = JSON.parse(localStorage.getItem('attendx_records') || '[]');

    const currentSessionData = activeSession || allSessions.find(s => s.id === sessionId);
    if (!currentSessionData) {
      setAnalyzing(false);
      return;
    }

    const courseSessions = allSessions.filter(s => s.courseId === currentSessionData.courseId);

    const realStats: StudentStats[] = records.map(r => {
      const studentHistoryForCourse = allRecords.filter(rec => 
        rec.matricNo === r.matricNo && 
        courseSessions.some(sess => sess.id === rec.sessionId)
      );

      const count = studentHistoryForCourse.length;
      const pct = courseSessions.length > 0 ? (count / courseSessions.length) * 100 : 0;

      return {
        matricNo: r.matricNo,
        name: r.studentName,
        sessionsAttended: count,
        totalSessions: courseSessions.length,
        percentage: pct,
        eligible: pct >= 75
      };
    });

    const insight = await analyzeAttendance(realStats);
    setAiInsights(insight);
    setAnalyzing(false);
  };

  const sessions: AttendanceSession[] = JSON.parse(localStorage.getItem('attendx_sessions') || '[]');
  const sessionData = activeSession || sessions.find(s => s.id === sessionId);

  if (!sessionData) {
    return (
      <Layout onLogout={onLogout} showLogout>
        <div className="text-center py-20">
          <h2 className="text-2xl font-bold text-gray-800">Session data unavailable.</h2>
          <Link to="/dashboard" className="text-blue-600 font-semibold hover:underline mt-4 inline-block">Return to Dashboard</Link>
        </div>
      </Layout>
    );
  }

  const course = COURSES.find(c => c.id === sessionData.courseId);
  const portalUrl = `${window.location.origin}${window.location.pathname}#/portal/${sessionData.id}`;

  return (
    <Layout title="Live Verification" onLogout={onLogout} showLogout>
      {/* Face Image Modal */}
      {selectedFace && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 p-4 animate-in fade-in" onClick={() => setSelectedFace(null)}>
           <div className="bg-white rounded-3xl p-2 max-w-sm w-full relative animate-in zoom-in duration-200">
             <img src={selectedFace} className="w-full aspect-square object-cover rounded-2xl" />
             <button className="absolute -top-4 -right-4 bg-white text-black w-10 h-10 rounded-full shadow-xl flex items-center justify-center font-bold">
               <i className="fas fa-times"></i>
             </button>
             <div className="p-4 text-center">
               <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Biometric Snapshot Captured at Login</p>
             </div>
           </div>
        </div>
      )}

      <div className="space-y-6">
        <div className="bg-white rounded-2xl shadow-sm border p-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <span className={`inline-block px-3 py-1 text-[10px] font-black rounded-full mb-2 uppercase tracking-widest ${sessionData.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}`}>
                {sessionData.active ? 'Active Verification' : 'Past Report'}
              </span>
              <h1 className="text-2xl font-bold text-gray-900">{course?.code}: {course?.name}</h1>
            </div>
            {sessionData.active && (
              <div className="bg-blue-600 text-white px-6 py-4 rounded-2xl text-center shadow-lg border-b-4 border-blue-800">
                <p className="text-[10px] font-bold uppercase tracking-widest text-blue-100 mb-1">Session Key</p>
                <p className="text-3xl font-black tracking-[0.2em]">{sessionData.sessionKey}</p>
              </div>
            )}
          </div>
          {sessionData.active && (
            <div className="mt-8 flex flex-col md:flex-row gap-4 items-center p-4 bg-blue-50 rounded-2xl border border-blue-100">
                <div className="flex-1 w-full">
                  <label className="block text-[10px] font-black text-blue-400 uppercase mb-1">Student Portal URL</label>
                  <div className="flex items-center space-x-2">
                    <input readOnly value={portalUrl} className="flex-1 bg-white border border-blue-200 rounded-lg px-3 py-2 text-xs text-gray-500 truncate" />
                    <button onClick={() => { navigator.clipboard.writeText(portalUrl); alert('Copied!'); }} className="bg-blue-600 text-white p-2 rounded-lg text-sm"><i className="fas fa-copy"></i></button>
                  </div>
                </div>
                <div className="px-8 border-l border-blue-200 text-center">
                    <span className="text-4xl font-black text-blue-700 leading-none">{records.length}</span>
                    <p className="text-[10px] font-black text-blue-400 uppercase">Present</p>
                </div>
            </div>
          )}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border overflow-hidden">
            <div className="p-4 border-b bg-gray-50 flex justify-between items-center">
              <h3 className="font-bold text-gray-800 text-sm uppercase tracking-widest">Attendance Roll</h3>
              <i className="fas fa-shield-alt text-blue-500"></i>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-white border-b">
                  <tr>
                    <th className="px-6 py-4 text-left text-[10px] font-black text-gray-400 uppercase tracking-widest">Student</th>
                    <th className="px-6 py-4 text-left text-[10px] font-black text-gray-400 uppercase tracking-widest">Matric No</th>
                    <th className="px-6 py-4 text-left text-[10px] font-black text-gray-400 uppercase tracking-widest">Time</th>
                    <th className="px-6 py-4 text-right text-[10px] font-black text-gray-400 uppercase tracking-widest">Face ID</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {records.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-16 text-center text-gray-400 italic text-sm">Waiting for verification requests...</td>
                    </tr>
                  ) : (
                    records.map(record => (
                      <tr key={record.id} className="hover:bg-blue-50/30 transition-colors">
                        <td className="px-6 py-4">
                          <div className="flex items-center space-x-3">
                            <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-xs">
                              {record.studentName.charAt(0)}
                            </div>
                            <span className="text-sm font-semibold text-gray-800">{record.studentName}</span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-sm font-bold text-gray-900">{record.matricNo}</td>
                        <td className="px-6 py-4 text-xs text-gray-500 font-medium">{new Date(record.timestamp).toLocaleTimeString()}</td>
                        <td className="px-6 py-4 text-right">
                          {record.faceImage ? (
                            <button 
                              onClick={() => setSelectedFace(record.faceImage!)}
                              className="text-[10px] font-black text-blue-600 bg-blue-50 hover:bg-blue-100 px-3 py-1 rounded-full uppercase tracking-tighter"
                            >
                              View ID
                            </button>
                          ) : (
                            <span className="text-[10px] text-gray-300 font-bold uppercase">No Photo</span>
                          )}
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>

          <div className="space-y-6">
            <div className="bg-white rounded-2xl shadow-sm border p-6">
              <h3 className="font-bold text-gray-800 text-sm uppercase tracking-widest mb-4">AI Insight Engine</h3>
              {aiInsights ? (
                <div className="bg-blue-50 p-4 rounded-xl text-xs text-blue-800 mb-4 leading-relaxed animate-in fade-in">
                   {aiInsights}
                </div>
              ) : (
                <p className="text-xs text-gray-400 mb-6 italic">Run analysis to see attendance trends and 75% threshold risk.</p>
              )}
              <button 
                onClick={runAiAnalysis} disabled={analyzing || records.length === 0}
                className="w-full bg-gray-900 hover:bg-black disabled:bg-gray-200 text-white font-bold py-3 rounded-xl transition-all flex items-center justify-center space-x-2 text-xs uppercase"
              >
                {analyzing ? <i className="fas fa-circle-notch fa-spin"></i> : <span>Analyze Records</span>}
              </button>
            </div>

            {sessionData.active && (
              <div className="bg-red-50 rounded-2xl border border-red-100 p-6">
                <button 
                  onClick={() => onEndSession(sessionData.id)}
                  className="w-full bg-red-600 hover:bg-red-700 text-white font-bold py-3 rounded-xl transition-all flex items-center justify-center space-x-2 text-xs uppercase shadow-lg shadow-red-200"
                >
                  <i className="fas fa-power-off"></i>
                  <span>End Session</span>
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </Layout>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';
import { DEPARTMENTS } from '../constants';
import { AttendanceSession, AttendanceRecord } from '../types';

function getDistanceInMeters(lat1: number, lon1: number, lat2: number, lon2: number) {
  const R = 6371e3;
  const phi1 = lat1 * Math.PI / 180;
  const phi2 = lat2 * Math.PI / 180;
  const deltaPhi = (lat2 - lat1) * Math.PI / 180;
  const deltaLambda = (lon2 - lon1) * Math.PI / 180;

  const a = Math.sin(deltaPhi / 2) * Math.sin(deltaPhi / 2) +
            Math.cos(phi1) * Math.cos(phi2) *
            Math.sin(deltaLambda / 2) * Math.sin(deltaLambda / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

export const StudentPortal: React.FC = () => {
  const { sessionId } = useParams<{ sessionId: string }>();
  const [name, setName] = useState('');
  const [matricNo, setMatricNo] = useState('');
  const [department, setDepartment] = useState('');
  const [sessionKey, setSessionKey] = useState('');
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [message, setMessage] = useState('');
  const [activeSession, setActiveSession] = useState<AttendanceSession | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [cameraActive, setCameraActive] = useState(false);

  useEffect(() => {
    const sessions: AttendanceSession[] = JSON.parse(localStorage.getItem('attendx_sessions') || '[]');
    const found = sessions.find(s => s.id === sessionId);
    if (found) {
      setActiveSession(found);
      startCamera();
    }
  }, [sessionId]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 400 }, height: { ideal: 400 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setCameraActive(true);
      }
    } catch (err) {
      console.error("Camera access denied:", err);
    }
  };

  const captureImage = () => {
    if (canvasRef.current && videoRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        context.drawImage(videoRef.current, 0, 0, 300, 300);
        return canvasRef.current.toDataURL('image/jpeg', 0.5);
      }
    }
    return undefined;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    performAttendanceCheck();
  };

  const performAttendanceCheck = async () => {
    setLoading(true);
    setStatus('idle');
    setMessage('');

    if (!activeSession || !activeSession.active) {
      setStatus('error');
      setMessage('This session is no longer active.');
      setLoading(false);
      return;
    }

    const deviceLockKey = `attendx_lock_${sessionId}`;
    const lockedMatric = localStorage.getItem(deviceLockKey);

    if (lockedMatric && lockedMatric.toUpperCase() !== matricNo.toUpperCase()) {
      setStatus('error');
      setMessage(`Security Alert: This device is locked to ${lockedMatric}.`);
      setLoading(false);
      return;
    }

    if (sessionKey.toUpperCase() !== activeSession.sessionKey) {
      setStatus('error');
      setMessage('Incorrect Session Key. Check with your lecturer.');
      setLoading(false);
      return;
    }

    const faceImage = captureImage();
    if (!faceImage && cameraActive) {
      setStatus('error');
      setMessage('Face capture failed. Please ensure camera is allowed.');
      setLoading(false);
      return;
    }

    // 3-STAGE LOCATION LOGIC (Fixed for Indoor reliability)
    const getLocation = (useHighAccuracy: boolean, timeout: number, maxAge: number) => {
      return new Promise<GeolocationPosition>((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, {
          enableHighAccuracy: useHighAccuracy,
          timeout: timeout,
          maximumAge: maxAge
        });
      });
    };

    let position: GeolocationPosition | null = null;

    try {
      // Attempt 1: High Accuracy (GPS)
      position = await getLocation(true, 10000, 0);
    } catch (e) {
      try {
        // Attempt 2: Low Accuracy (Network/Cell) - Much more reliable for indoors
        console.warn("GPS timed out, trying network positioning...");
        position = await getLocation(false, 15000, 30000);
      } catch (e2) {
        setStatus('error');
        setMessage('Location error: Unable to fix position. If you are indoors, try moving closer to a window.');
        setLoading(false);
        return;
      }
    }

    if (!position) return;

    const distance = getDistanceInMeters(
      position.coords.latitude,
      position.coords.longitude,
      activeSession.location.lat,
      activeSession.location.lng
    );

    const allowedRadius = activeSession.radius + 75; // 75m buffer for indoor accuracy drift

    if (distance > allowedRadius) {
       setStatus('error');
       setMessage(`Too far from lecture hall (${Math.round(distance)}m). You must be present in class.`);
       setLoading(false);
       return;
    }

    const records: AttendanceRecord[] = JSON.parse(localStorage.getItem('attendx_records') || '[]');
    const alreadySubmitted = records.some(r => r.sessionId === sessionId && r.matricNo.toUpperCase() === matricNo.toUpperCase());

    if (alreadySubmitted) {
      setStatus('error');
      setMessage('Attendance already recorded.');
      setLoading(false);
      return;
    }

    const newRecord: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      sessionId: sessionId!,
      studentName: name,
      matricNo: matricNo.toUpperCase(),
      department: department,
      timestamp: Date.now(),
      faceImage: faceImage,
      location: {
        lat: position.coords.latitude,
        lng: position.coords.longitude
      }
    };

    localStorage.setItem('attendx_records', JSON.stringify([...records, newRecord]));
    localStorage.setItem(deviceLockKey, matricNo.toUpperCase());

    setStatus('success');
    setMessage(`Verified! Attendance logged for ${name}.`);
    setLoading(false);
  };

  if (!activeSession) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 rounded-2xl shadow-lg text-center max-w-sm">
